Insert into ADMIN.NOTICE (NOTICE_NO,USER_ID,TITLE,CONTENTS,CNT,CDATETIME,UDATETIME) values (11,'admin01','AGRICOLA 오픈 안내','안녕하세요. 농수산물 직거래 플랫폼 AGRICOLA가 정식 오픈했습니다! 
생산자와 소비자가 직접 연결되는 믿을 수 있는 직거래 서비스를 이용해보세요.',128,to_date('25/10/30','RR/MM/DD'),to_date('25/10/30','RR/MM/DD'));
Insert into ADMIN.NOTICE (NOTICE_NO,USER_ID,TITLE,CONTENTS,CNT,CDATETIME,UDATETIME) values (12,'admin01','회원가입 이벤트 진행 중','지금 회원가입하시면 3,000원 할인 쿠폰을 드립니다. 
신선한 농수산물을 합리적인 가격에 만나보세요!',224,to_date('25/10/30','RR/MM/DD'),to_date('25/10/30','RR/MM/DD'));
Insert into ADMIN.NOTICE (NOTICE_NO,USER_ID,TITLE,CONTENTS,CNT,CDATETIME,UDATETIME) values (13,'admin01','배송 지연 안내','최근 폭우로 일부 지역의 신선식품 배송이 지연되고 있습니다. 
고객님의 너른 양해 부탁드립니다.',195,to_date('25/10/30','RR/MM/DD'),to_date('25/10/30','RR/MM/DD'));
Insert into ADMIN.NOTICE (NOTICE_NO,USER_ID,TITLE,CONTENTS,CNT,CDATETIME,UDATETIME) values (14,'admin01','번쩍장터 서비스 오픈 안내','지금 바로 실시간 거래 가능한 번쩍장터 서비스를 만나보세요! 
지역 판매자와 바로 연결되는 빠른 거래를 지원합니다.',259,to_date('25/10/30','RR/MM/DD'),to_date('25/10/30','RR/MM/DD'));
Insert into ADMIN.NOTICE (NOTICE_NO,USER_ID,TITLE,CONTENTS,CNT,CDATETIME,UDATETIME) values (15,'admin01','정기 점검 안내 (11월 1일 02:00~05:00)','더 나은 서비스 제공을 위해 AGRICOLA 시스템 점검이 진행됩니다. 
해당 시간 동안 접속이 불가하오니 이용에 참고 부탁드립니다.',103,to_date('25/10/30','RR/MM/DD'),to_date('25/10/30','RR/MM/DD'));
Insert into ADMIN.NOTICE (NOTICE_NO,USER_ID,TITLE,CONTENTS,CNT,CDATETIME,UDATETIME) values (16,'admin01','판매자 신청 기능 오픈','이제 누구나 AGRICOLA 판매자로 등록할 수 있습니다. 
직접 재배한 농수산물을 판매해보세요!',343,to_date('25/10/30','RR/MM/DD'),to_date('25/10/30','RR/MM/DD'));
Insert into ADMIN.NOTICE (NOTICE_NO,USER_ID,TITLE,CONTENTS,CNT,CDATETIME,UDATETIME) values (17,'admin01','리뷰 이벤트 당첨자 발표','지난 10월 리뷰 작성 이벤트 당첨자를 발표합니다. 
당첨자 명단은 고객센터 > 이벤트 페이지에서 확인 가능합니다.',281,to_date('25/10/30','RR/MM/DD'),to_date('25/10/30','RR/MM/DD'));
Insert into ADMIN.NOTICE (NOTICE_NO,USER_ID,TITLE,CONTENTS,CNT,CDATETIME,UDATETIME) values (18,'admin01','친환경 포장재 변경 안내','AGRICOLA는 환경 보호를 위해 모든 포장재를 친환경 소재로 전환합니다. 
지속 가능한 농업과 소비에 함께 동참해주세요.',165,to_date('25/10/30','RR/MM/DD'),to_date('25/10/30','RR/MM/DD'));
Insert into ADMIN.NOTICE (NOTICE_NO,USER_ID,TITLE,CONTENTS,CNT,CDATETIME,UDATETIME) values (19,'admin01','고객센터 운영시간 변경 안내','고객센터 운영시간이 오전 9시~오후 6시로 변경됩니다. 
주말 및 공휴일은 휴무입니다.',97,to_date('25/10/30','RR/MM/DD'),to_date('25/10/30','RR/MM/DD'));
Insert into ADMIN.NOTICE (NOTICE_NO,USER_ID,TITLE,CONTENTS,CNT,CDATETIME,UDATETIME) values (20,'admin01','11월 신상품 입고 안내','<p>제철 농산물과 수산물이 새롭게 입고되었습니다. 
신선한 가을 농수산물을 지금 바로 만나보세요!!</p>',368,to_date('25/10/30','RR/MM/DD'),to_date('25/10/31','RR/MM/DD'));
