Insert into ADMIN.PRODUCT (PRODUCT_NO,SELLER_ID,CATEGORY_NO,PNAME,PINFO,PRICE,ORIGIN,CDATETIME,UDATETIME,RECOMMEND,PRODUCT_STATUS,IS_SUBSCRIPTION,SHIPPING_TYPE) values (261,'seller03',4300,'광천 재래김(전장)','충남 광천에서 생산한 재래김입니다. 전장 김으로 구워져 나와 밥반찬, 김밥용으로 활용하기 좋습니다.',9800,'충청남도 광천',to_date('25/11/29','RR/MM/DD'),to_date('26/01/16','RR/MM/DD'),'N','SELLING','N','ROOM');
Insert into ADMIN.PRODUCT (PRODUCT_NO,SELLER_ID,CATEGORY_NO,PNAME,PINFO,PRICE,ORIGIN,CDATETIME,UDATETIME,RECOMMEND,PRODUCT_STATUS,IS_SUBSCRIPTION,SHIPPING_TYPE) values (263,'seller01',1310,'나주 신고배','전남 나주에서 재배한 신고배입니다. 당도가 높고 과육이 아삭아삭해 선물용으로도 인기가 많습니다.',32000,'전라남도 나주',to_date('25/11/29','RR/MM/DD'),to_date('26/01/16','RR/MM/DD'),'N','SELLING','N','ROOM');
Insert into ADMIN.PRODUCT (PRODUCT_NO,SELLER_ID,CATEGORY_NO,PNAME,PINFO,PRICE,ORIGIN,CDATETIME,UDATETIME,RECOMMEND,PRODUCT_STATUS,IS_SUBSCRIPTION,SHIPPING_TYPE) values (264,'seller01',1300,'아삭한 부사 사과','당도 높은 부사 품종 사과입니다. 아삭한 식감과 풍부한 과즙으로 간식, 디저트용으로 좋습니다.',20000,'국내산(경북/충북 산지 혼합)',to_date('25/11/29','RR/MM/DD'),to_date('26/01/16','RR/MM/DD'),'N','SELLING','N','ROOM');
Insert into ADMIN.PRODUCT (PRODUCT_NO,SELLER_ID,CATEGORY_NO,PNAME,PINFO,PRICE,ORIGIN,CDATETIME,UDATETIME,RECOMMEND,PRODUCT_STATUS,IS_SUBSCRIPTION,SHIPPING_TYPE) values (265,'seller02',2000,'횡성 한우 1+등급 구이 세트','강원도 횡성에서 사육한 1+ 등급 한우로 구성한 구이 세트입니다. 등심·채끝·목심을 소량씩 다양하게 맛볼 수 있는 구성입니다.',89000,'강원도 횡성',to_date('25/11/29','RR/MM/DD'),to_date('26/01/16','RR/MM/DD'),'N','SELLING','N','ROOM');
Insert into ADMIN.PRODUCT (PRODUCT_NO,SELLER_ID,CATEGORY_NO,PNAME,PINFO,PRICE,ORIGIN,CDATETIME,UDATETIME,RECOMMEND,PRODUCT_STATUS,IS_SUBSCRIPTION,SHIPPING_TYPE) values (267,'seller01',1040,'유기농 잡곡 혼합 세트','유기농 현미, 찹쌀, 귀리, 서리태 등을 균형 있게 섞은 혼합 잡곡입니다. 밥 지을 때 흰쌀과 함께 넣어 드시면 고소한 풍미를 느낄 수 있습니다.',13900,'국내산',to_date('25/11/29','RR/MM/DD'),to_date('26/01/16','RR/MM/DD'),'N','SELLING','N','ROOM');
Insert into ADMIN.PRODUCT (PRODUCT_NO,SELLER_ID,CATEGORY_NO,PNAME,PINFO,PRICE,ORIGIN,CDATETIME,UDATETIME,RECOMMEND,PRODUCT_STATUS,IS_SUBSCRIPTION,SHIPPING_TYPE) values (268,'seller01',1440,'샐러드용 믹스 채소','양상추, 로메인, 어린잎 채소 등을 깨끗이 세척·손질하여 섞은 샐러드 전용 채소입니다. 개봉 후 바로 드실 수 있도록 간편 포장했습니다.',6900,'국내산',to_date('25/11/29','RR/MM/DD'),to_date('26/01/16','RR/MM/DD'),'N','SELLING','N','ROOM');
Insert into ADMIN.PRODUCT (PRODUCT_NO,SELLER_ID,CATEGORY_NO,PNAME,PINFO,PRICE,ORIGIN,CDATETIME,UDATETIME,RECOMMEND,PRODUCT_STATUS,IS_SUBSCRIPTION,SHIPPING_TYPE) values (269,'seller01',1220,'달콤한 방울토마토','당도가 높은 방울토마토로, 샐러드나 간식용으로 가볍게 드시기 좋습니다.',5300,'국내산',to_date('25/11/29','RR/MM/DD'),to_date('26/01/16','RR/MM/DD'),'N','SELLING','N','ROOM');
