Insert into ADMIN.REGION_SPECIAL (REGION_ID,REGION_NAME,TITLE,DESCRIPTION,THUMBNAIL_URL,BASE_PRICE,IS_ACTIVE,DISPLAY_ORDER,CDATETIME,UDATETIME) values (1,'강원도','강원 햇감자·옥수수 실속 박스','강원도 고랭지에서 수확한 햇감자와 옥수수를 한 번에 받아보는 실속 구성입니다. 포슬포슬한 감자와 달콤한 옥수수를 산지 직송으로 보내드립니다.','/resources/uploads/regional/reg01.jpg',33400,'Y',1,to_date('26/01/14','RR/MM/DD'),to_date('26/01/14','RR/MM/DD'));
Insert into ADMIN.REGION_SPECIAL (REGION_ID,REGION_NAME,TITLE,DESCRIPTION,THUMBNAIL_URL,BASE_PRICE,IS_ACTIVE,DISPLAY_ORDER,CDATETIME,UDATETIME) values (2,'제주도','제주 감귤·한라봉 과일 박스','제주 현지 농가에서 수확한 감귤과 한라봉을 함께 담은 과일 박스입니다. 산지에서 바로 수확한 과일만 선별하여 배송합니다.','/resources/uploads/regional/reg02.jpg',52700,'Y',2,to_date('26/01/14','RR/MM/DD'),to_date('26/01/14','RR/MM/DD'));
Insert into ADMIN.REGION_SPECIAL (REGION_ID,REGION_NAME,TITLE,DESCRIPTION,THUMBNAIL_URL,BASE_PRICE,IS_ACTIVE,DISPLAY_ORDER,CDATETIME,UDATETIME) values (3,'충청남도','광천 김·멸치 바다 반찬 세트','충남 광천에서 생산한 재래김과 국물용 멸치를 한 번에 즐길 수 있는 바다 반찬 세트입니다. 밥반찬, 국물 내기에 모두 활용하기 좋습니다.','/resources/uploads/regional/reg03.jpg',25700,'Y',3,to_date('26/01/14','RR/MM/DD'),to_date('26/01/14','RR/MM/DD'));
Insert into ADMIN.REGION_SPECIAL (REGION_ID,REGION_NAME,TITLE,DESCRIPTION,THUMBNAIL_URL,BASE_PRICE,IS_ACTIVE,DISPLAY_ORDER,CDATETIME,UDATETIME) values (4,'전라남도','나주 배·사과 혼합 과일 박스','아삭한 나주 배와 달콤한 사과를 함께 담은 혼합 과일 박스입니다. 선물용으로도 좋은 고급 과일 구성입니다.','/resources/uploads/regional/reg04.jpg',52000,'Y',4,to_date('26/01/14','RR/MM/DD'),to_date('26/01/14','RR/MM/DD'));
Insert into ADMIN.REGION_SPECIAL (REGION_ID,REGION_NAME,TITLE,DESCRIPTION,THUMBNAIL_URL,BASE_PRICE,IS_ACTIVE,DISPLAY_ORDER,CDATETIME,UDATETIME) values (5,'강원도 횡성','횡성 한우 구이 실속 세트','강원도 횡성에서 사육한 1+ 등급 한우로 구성된 구이용 세트입니다. 등심·목심·채끝을 소량씩 다양하게 맛볼 수 있는 실속 구성입니다.','/resources/uploads/regional/reg05.jpg',89000,'Y',5,to_date('26/01/14','RR/MM/DD'),to_date('26/01/14','RR/MM/DD'));
