Insert into ADMIN.SUBSCRIPTION_PLAN (PLAN_ID,PLAN_NAME,DESCRIPTION,SHORT_DESC,PERIOD_TYPE,BASE_PRICE,THUMBNAIL_URL,IS_ACTIVE,DISPLAY_ORDER,CDATETIME,UDATETIME) values (1,'주 1회 제철 채소 꾸러미','국내 각지 소농의 제철 채소 8~10종을 매주 한 번씩 받아보는 꾸러미입니다. 샐러드·국거리·볶음 요리에 두루 활용할 수 있도록 균형 있게 구성합니다.','제철 채소 8~10종, 주 1회 배송','WEEKLY',35900,'/resources/uploads/subscription/plan01.jpg','Y',1,to_date('26/01/14','RR/MM/DD'),to_date('26/01/14','RR/MM/DD'));
Insert into ADMIN.SUBSCRIPTION_PLAN (PLAN_ID,PLAN_NAME,DESCRIPTION,SHORT_DESC,PERIOD_TYPE,BASE_PRICE,THUMBNAIL_URL,IS_ACTIVE,DISPLAY_ORDER,CDATETIME,UDATETIME) values (2,'격주 과일 혼합 박스','사과, 배, 감귤, 제철 과일 등을 혼합하여 2주에 한 번 배송하는 과일 박스입니다. 가정용으로 먹기 좋은 실속형 구성을 기본으로 합니다.','2주마다 도착하는 과일 혼합 박스','BIWEEKLY',42000,'/resources/uploads/subscription/plan02.jpg','Y',2,to_date('26/01/14','RR/MM/DD'),to_date('26/01/14','RR/MM/DD'));
Insert into ADMIN.SUBSCRIPTION_PLAN (PLAN_ID,PLAN_NAME,DESCRIPTION,SHORT_DESC,PERIOD_TYPE,BASE_PRICE,THUMBNAIL_URL,IS_ACTIVE,DISPLAY_ORDER,CDATETIME,UDATETIME) values (3,'월 1회 유기농 잡곡 세트','유기농 인증을 받은 현미, 귀리, 찹쌀, 서리태 등을 포함한 혼합 잡곡 세트입니다. 한 달에 한 번씩 정기적으로 받아보며 건강한 식단을 유지해 보세요.','유기농 잡곡 4~5종, 월 1회 배송','MONTHLY',29800,'/resources/uploads/subscription/plan03.jpg','Y',3,to_date('26/01/14','RR/MM/DD'),to_date('26/01/14','RR/MM/DD'));
Insert into ADMIN.SUBSCRIPTION_PLAN (PLAN_ID,PLAN_NAME,DESCRIPTION,SHORT_DESC,PERIOD_TYPE,BASE_PRICE,THUMBNAIL_URL,IS_ACTIVE,DISPLAY_ORDER,CDATETIME,UDATETIME) values (4,'주 1회 샐러드 채소 박스','양상추, 로메인, 어린잎 채소, 방울토마토 등 샐러드용 채소를 중심으로 구성한 주 1회 배송 박스입니다. 간편한 샐러드 레시피 카드도 함께 제공됩니다.','샐러드용 채소 위주, 주 1회 배송','WEEKLY',32900,'/resources/uploads/subscription/plan04.jpg','Y',4,to_date('26/01/14','RR/MM/DD'),to_date('26/01/14','RR/MM/DD'));
Insert into ADMIN.SUBSCRIPTION_PLAN (PLAN_ID,PLAN_NAME,DESCRIPTION,SHORT_DESC,PERIOD_TYPE,BASE_PRICE,THUMBNAIL_URL,IS_ACTIVE,DISPLAY_ORDER,CDATETIME,UDATETIME) values (5,'월 1회 농가 추천 박스','시기에 맞는 제철 농산물을 생산자가 직접 추천하여 구성하는 서프라이즈 박스입니다. 매월 다른 구성으로 농가의 다양한 상품을 경험해 보세요.','매달 구성이 바뀌는 농가 추천 박스','MONTHLY',45000,'/resources/uploads/subscription/plan05.jpg','Y',5,to_date('26/01/14','RR/MM/DD'),to_date('26/01/14','RR/MM/DD'));
